def transform(grid):
    """Collapse each 3x3 patch to its non-background color (0/5 are background)."""
    result = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            colors = {grid[i][j] for i in range(r, min(r + 3, len(grid)))
                      for j in range(c, min(c + 3, len(grid[0]))) if grid[i][j] not in (0, 5)}
            row.append(next(iter(colors)) if colors else 0)
        result.append(row)
    return result
